import type { ReportDefinition } from '../types/report';
import type { ReportDataSource } from '../types/datasource';

export type PdfRequest = (report: ReportDefinition, data: Record<string, unknown>[], dataSource: ReportDataSource, refresh?: boolean) => Promise<Blob>;
export function createPdfClient(endpoint = '/api/report-pdf', fetcher: typeof fetch = (...args) => fetch(...args)): PdfRequest {
let cached: { key: string; promise: Promise<Blob> } | undefined;
/** Preview and download share the same generated bytes for the current report/data snapshot. */
return function requestReportPdf(report: ReportDefinition, data: Record<string, unknown>[], dataSource: ReportDataSource, refresh = false): Promise<Blob> {
  const body = { report, data, dataSource, timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone };
  const key = JSON.stringify(body);
  if (!refresh && cached?.key === key) return cached.promise;
  const promise = fetcher(endpoint, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...body, executionTime: new Date().toISOString() }),
  }).then(async response => {
    if (!response.ok) {
      const result = await response.json().catch(() => null);
      throw new Error(result?.error ?? `PDF service unavailable (${response.status})`);
    }
    if (!response.headers.get('content-type')?.includes('application/pdf')) throw new Error('PDF service returned an unexpected response');
    return response.blob();
  });
  cached = { key, promise };
  void promise.catch(() => { if (cached?.promise === promise) cached = undefined; });
  return promise;
}

}
export const requestReportPdf = createPdfClient();
